def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 98:
        return 'D'

    opp_def = 0
    my_def = 0
    for me, opp in history:
        if opp == 'D':
            opp_def += 1
        if me == 'D':
            my_def += 1

    if opp_def * 5 > n * 4:
        return 'D'

    if opp_def == 0:
        if n < 5:
            return 'C'
        else:
            return 'D'
    else:
        if my_def == 0:
            if history[-1][1] == 'D':
                return 'D'
            else:
                return 'C'
        else:
            if history[-1][1] == 'D':
                if history[-1][0] == 'D':
                    return 'C'
                else:
                    if n >= 2 and history[-1][0] == 'C' and history[-2][0] == 'C':
                        return 'D'
                    else:
                        return 'C'
            else:
                return 'C'
